from functools import wraps
def counted(fn):
    calls = 0
    @wraps(fn)
    def wrapper(*args, **kwargs):
        nonlocal calls
        calls += 1
        return fn(*args, **kwargs), calls
    return wrapper
@counted
def double(x): return x * 2
print(double(3))

