from typing import Protocol
class Store(Protocol):
    def get(self, key: str) -> str | None: ...
def read_name(store: Store) -> str:
    value = store.get("name")
    return value if value is not None else "guest"

import json
def decode_response(status, body):
    if status != 200:
        raise RuntimeError("upstream status")
    value = json.loads(body)
    if not isinstance(value, dict) or not isinstance(value.get("id"), int):
        raise ValueError("invalid schema")
    return value["id"]
print(decode_response(200, '{"id": 7}'))

from functools import lru_cache
@lru_cache(maxsize=128)
def fib(n):
    if n < 2: return n
    return fib(n - 1) + fib(n - 2)
print(fib(20))
print(fib.cache_info())

def apply_once(store, key, amount):
    if key in store:
        previous = store[key]
        if previous[0] != amount: raise ValueError("conflict")
        return previous[1]
    result = amount * 2
    store[key] = (amount, result)
    return result
s = {}
print(apply_once(s, "a", 3), apply_once(s, "a", 3))

def place_order(command, repository):
    if command["total"] <= 0: raise ValueError("invalid total")
    existing = repository.get(command["key"])
    if existing is not None: return existing
    order = {"id": command["key"], "status": "new"}
    repository[command["key"]] = order
    return order
print(place_order({"key": "o1", "total": 100}, {}))
